import { SKILL_TRACKS } from './data';
import { SkillIcon } from './icons';

/** Whole-word, case-insensitive match on any of `words` (each may hold regex, e.g. `animat\w*`). */
const w = (...words: string[]) => new RegExp(`(?<![\\w-])(?:${words.join('|')})(?![\\w-])`, 'i');

/* ---------- 1. other tools, by name ---------- */

/** Extra spellings used in topic names. */
const ALIASES: Record<string, string[]> = {
  node: ['Node'],
  vue: ['Vue'],
  express: ['Express'],
  nuxt: ['Nuxt'],
  'tailwind-css': ['Tailwind'],
  postgresql: ['Postgres'],
  'ruby-on-rails': ['Rails'],
  'google-cloud': ['GCP'],
  'material-ui': ['MUI'],
  'android-sdk': ['Android'],
};
/** Phrases where a tool's name means something else. */
const NOT_A_TOOL = /Node exporter|Worker nodes|Kafka Streams|Docker actions/;

const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&');
const BRANDS: { id: string; icon: string; re: RegExp }[] = [];
for (const track of SKILL_TRACKS)
  for (const group of track.groups)
    for (const tool of group.tools) {
      if (tool.id === 'go' || BRANDS.some((b) => b.id === tool.id)) continue; // "Go" is too common a word
      const names = [tool.name, ...(ALIASES[tool.id] ?? [])].map(esc).join('|');
      BRANDS.push({ id: tool.id, icon: tool.icon, re: new RegExp(`(?<![\\w-])(?:${names})(?![\\w-])`) });
    }

