  'Rules & declarations': Paintbrush, 'Custom properties': Variable, 'z-index & stacking context': Layers,
  'Media queries': MonitorSmartphone, 'css:Breakpoints': MonitorSmartphone, 'bootstrap:Breakpoints': MonitorSmartphone,
  'Animation properties': Sparkles, 'View transitions': Sparkles, 'CSS-in-JS': Paintbrush, 'Changing styles & classes': Paintbrush,
  'Flex container': Columns3, 'Grid container': LayoutGrid, 'Container queries': MonitorSmartphone, 'Container': Columns3,
  'Rest parameters': SquareFunction, 'Data types': Binary, 'null & undefined': Binary, 'includes & indexOf': Search,
  'The event loop': Repeat, 'Proxy & Reflect': Wand2, 'Statements & semicolons': Code, 'Operators': Scale,
