type Pick = { brand: { id: string; icon: string } } | { Icon: LucideIcon; name: string };

function pick(topic: string, section: string, toolId: string): Pick {
  const hand = OVERRIDES[`${toolId}:${topic}`] ?? OVERRIDES[topic];
  if (hand) return { Icon: hand, name: hand.displayName ?? '?' };
  if (!NOT_A_TOOL.test(topic)) {
    const brand = BRANDS.find((b) => b.id !== toolId && b.re.test(topic));
    if (brand) return { brand };
  }
  const Icon = RULES.find(([re]) => re.test(topic))?.[1] ?? RULES.find(([re]) => re.test(section))?.[1];
  return Icon ? { Icon, name: Icon.displayName ?? '?' } : { Icon: CircleDot, name: 'FALLBACK' };
}

/** The icon for one topic tile. `toolId` is the page's own tool, which never shows as a brand match. */
export function topicIcon(topic: string, section: string, toolId: string): ReactNode {
  const p = pick(topic, section, toolId);
  if ('brand' in p) return <SkillIcon name={p.brand.icon} size={22} />;
  return <p.Icon size={19} strokeWidth={1.9} aria-hidden />;
}

/** For auditing the rules: the icon a topic resolves to, by name. */
export const topicIconName = (topic: string, section: string, toolId: string) => {
  const p = pick(topic, section, toolId);
  return 'brand' in p ? `brand:${p.brand.id}` : p.name;
};
